import{_ as h}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as p,D as o,o as s,c as g,I as i,w as k,k as l,a as m,R as n,b as u,e as A}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const T=JSON.parse('{"title":"smolagents 源码导读","description":"","frontmatter":{"title":"smolagents 源码导读","author":"阿源","date":"2026/10/09 00:00","categories":["Agent 开发"],"tags":["smolagents","Source Reading","Code Agent"],"status":"正文","chapter":11},"headers":[],"relativePath":"courses/agent/11-源码精读/01-smolagents源码导读.md","filePath":"courses/agent/11-源码精读/01-smolagents源码导读.md","lastUpdated":1791548774000}'),y={name:"courses/agent/11-源码精读/01-smolagents源码导读.md"},_=l("h1",{id:"smolagents-源码导读",tabindex:"-1"},[m("smolagents 源码导读 "),l("a",{class:"header-anchor",href:"#smolagents-源码导读","aria-label":'Permalink to "smolagents 源码导读"'},"​")],-1),C=n('<p>smolagents 是五个项目里最适合先读的一个：它把 Agent Loop、模型适配、工具调用和代码执行压缩在很小的 Python 代码面里。本文的目标不是背 API，而是沿着一次 <code>run()</code> 找到“模型决定什么、框架保存什么、执行器做什么、何时结束”。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能从 <code>MultiStepAgent.run()</code> 追到一次模型调用、动作解析、工具或代码执行和最终答案。</li><li>能分清 <code>CodeAgent</code>、<code>ToolCallingAgent</code>、<code>Model</code>、<code>AgentMemory</code> 与执行器的责任。</li><li>能解释为什么 <code>LocalPythonExecutor</code> 的限制不是安全沙箱，以及真正的隔离边界在哪里。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>第 02–10 章的 Agent Loop、Tool、State、Trace、Sandbox。</li><li>Python 的类、生成器、异常和上下文管理器；不要求先学完整框架。</li></ul><h2 id="版本与源码范围-2026-10-09" tabindex="-1">版本与源码范围（2026-10-09） <a class="header-anchor" href="#版本与源码范围-2026-10-09" aria-label="Permalink to &quot;版本与源码范围（2026-10-09）&quot;">​</a></h2><p>本次核对的是官方仓库 <code>huggingface/smolagents</code> 的 <code>main</code> 分支。仓库语言为 Python；<code>pyproject.toml</code> 当前开发版本为 <code>1.27.0.dev0</code>，最近稳定发布为 <code>v1.26.0</code>。版本号会继续变化，读源码时应以提交或 release tag 固定环境。</p><table><thead><tr><th>先看什么</th><th>当前路径</th><th>解决什么问题</th></tr></thead><tbody><tr><td>Agent 运行骨架</td><td><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/agents.py" target="_blank" rel="noreferrer"><code>src/smolagents/agents.py</code></a></td><td>Loop、步骤、工具调用、代码 Agent</td></tr><tr><td>步骤记忆</td><td><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/memory.py" target="_blank" rel="noreferrer"><code>src/smolagents/memory.py</code></a></td><td>将 system/task/action/result 组织成历史</td></tr><tr><td>模型适配</td><td><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/models.py" target="_blank" rel="noreferrer"><code>src/smolagents/models.py</code></a></td><td>不同供应商的消息与流式结果</td></tr><tr><td>Python 执行</td><td><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/local_python_executor.py" target="_blank" rel="noreferrer"><code>src/smolagents/local_python_executor.py</code></a></td><td>解析、限制并执行模型生成的代码</td></tr><tr><td>工具抽象</td><td><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/tools.py" target="_blank" rel="noreferrer"><code>src/smolagents/tools.py</code></a></td><td>工具描述、参数 schema 与调用</td></tr></tbody></table><h2 id="先看懂整体调用链" tabindex="-1">先看懂整体调用链 <a class="header-anchor" href="#先看懂整体调用链" aria-label="Permalink to &quot;先看懂整体调用链&quot;">​</a></h2>',9),b=n('<p>阅读提示：图中的“继续”不是递归调用一个新 Agent，而是同一个 <code>MultiStepAgent</code> 把新步骤追加到 memory，再生成下一轮模型输入。先在 <code>run</code> 设置断点，再沿 <code>_run_stream → _step_stream</code> 下钻，比从工具类随机阅读更容易建立主线。</p><h2 id="multistepagent-公共运行骨架" tabindex="-1"><code>MultiStepAgent</code>：公共运行骨架 <a class="header-anchor" href="#multistepagent-公共运行骨架" aria-label="Permalink to &quot;`MultiStepAgent`：公共运行骨架&quot;">​</a></h2><p><code>MultiStepAgent</code> 是抽象基类，负责通用的运行生命周期：初始化 system prompt、准备工具和托管 Agent、建立 memory、循环执行步骤、达到最终答案或最大步数后返回 <code>RunResult</code>。它不决定“动作是 JSON 工具调用还是 Python 代码”，这个差异交给子类的 <code>_step_stream()</code>。</p><h3 id="multistepagent-init" tabindex="-1"><code>MultiStepAgent.__init__</code> <a class="header-anchor" href="#multistepagent-init" aria-label="Permalink to &quot;`MultiStepAgent.__init__`&quot;">​</a></h3><p>入口会保存 <code>model</code>、<code>tools</code>、<code>managed_agents</code>、<code>max_steps</code> 和回调，并把基础工具加入工具表。读这里时重点问两个问题：工具描述什么时候生成？托管 Agent 以什么形式暴露给模型？这两个答案直接影响模型能否发现能力。</p><h3 id="multistepagent-run" tabindex="-1"><code>MultiStepAgent.run</code> <a class="header-anchor" href="#multistepagent-run" aria-label="Permalink to &quot;`MultiStepAgent.run`&quot;">​</a></h3><p><code>run(task, ...)</code> 是同步外观；真正的步骤流在 <code>_run_stream()</code>。它通常负责创建一次运行的 memory、把任务放到历史、逐步消费 step stream，并把中间结果或最终结果返回。不要把 <code>run()</code> 当作“只调用一次模型”的函数。</p><h3 id="multistepagent-run-stream" tabindex="-1"><code>MultiStepAgent._run_stream</code> <a class="header-anchor" href="#multistepagent-run-stream" aria-label="Permalink to &quot;`MultiStepAgent._run_stream`&quot;">​</a></h3><p>这里是最值得下断点的位置：它把“开始一轮”“执行一步”“记录步骤”“检查最终答案”“超过 <code>max_steps</code> 的错误处理”串起来。源码阅读时在循环体旁记录一张表：输入 memory、模型输出、执行副作用、写回 memory、停止原因。</p><h3 id="multistepagent-step-stream" tabindex="-1"><code>MultiStepAgent._step_stream</code> <a class="header-anchor" href="#multistepagent-step-stream" aria-label="Permalink to &quot;`MultiStepAgent._step_stream`&quot;">​</a></h3><p>这是子类扩展点。<code>ToolCallingAgent</code> 在这里解析模型的工具调用；<code>CodeAgent</code> 在这里提取代码块并交给 Python 执行器。若要实现新的 Agent 形式，先确认该方法要返回哪些 step/stream 事件，再决定是否复用父类的停止与持久化逻辑。</p><h2 id="codeagent-模型写代码-执行器解释代码" tabindex="-1"><code>CodeAgent</code>：模型写代码，执行器解释代码 <a class="header-anchor" href="#codeagent-模型写代码-执行器解释代码" aria-label="Permalink to &quot;`CodeAgent`：模型写代码，执行器解释代码&quot;">​</a></h2><p><code>CodeAgent</code> 不是“让模型写一个项目然后直接运行”，而是让模型在固定的 action 格式里写一段可执行代码，用工具、变量和 <code>final_answer</code> 产生下一步结果。它的核心风险也因此从“参数校验”变成了“代码解释和副作用隔离”。</p><h3 id="codeagent-create-python-executor" tabindex="-1"><code>CodeAgent.create_python_executor</code> <a class="header-anchor" href="#codeagent-create-python-executor" aria-label="Permalink to &quot;`CodeAgent.create_python_executor`&quot;">​</a></h3><p>该方法选择执行器。默认本地执行器适合学习和受信输入；接入 Docker、E2B、Modal 等外部执行器时，真正的安全边界由外部运行环境提供，而不是由 Agent 类本身提供。</p><h3 id="codeagent-step-stream" tabindex="-1"><code>CodeAgent._step_stream</code> <a class="header-anchor" href="#codeagent-step-stream" aria-label="Permalink to &quot;`CodeAgent._step_stream`&quot;">​</a></h3><p>阅读顺序是：拿到模型文本 → 提取代码 → 将工具和受控变量送入 executor → 收集 <code>CodeOutput</code> → 识别 <code>final_answer</code> 或错误 → 写入 <code>ActionStep</code>。注意“模型生成了代码”和“代码产生了副作用”是两个不同事件，审计和重试策略不能混在一起。</p><h2 id="toolcallingagent-结构化工具调用路径" tabindex="-1"><code>ToolCallingAgent</code>：结构化工具调用路径 <a class="header-anchor" href="#toolcallingagent-结构化工具调用路径" aria-label="Permalink to &quot;`ToolCallingAgent`：结构化工具调用路径&quot;">​</a></h2><p><code>ToolCallingAgent</code> 让模型输出结构化工具调用，而不是 Python 程序。它更容易做参数 schema 校验和工具级授权，但多步表达能力由模型的多次调用与工具结果回填提供。</p><h3 id="toolcallingagent-process-tool-calls" tabindex="-1"><code>ToolCallingAgent.process_tool_calls</code> <a class="header-anchor" href="#toolcallingagent-process-tool-calls" aria-label="Permalink to &quot;`ToolCallingAgent.process_tool_calls`&quot;">​</a></h3><p>该方法把模型响应中的调用逐个转换为工具执行，处理工具不存在、参数错误和工具自身异常。源码阅读时要看异常是“返回给模型继续修正”，还是“直接终止这次 run”；这决定了错误属于可恢复观察，还是终止条件。</p><h3 id="toolcallingagent-execute-tool-call" tabindex="-1"><code>ToolCallingAgent.execute_tool_call</code> <a class="header-anchor" href="#toolcallingagent-execute-tool-call" aria-label="Permalink to &quot;`ToolCallingAgent.execute_tool_call`&quot;">​</a></h3><p>这里是工具名到 Python <code>Tool</code> 对象的派发点。重点观察名称查找、参数转换、状态变量替换和输出格式化；不要只看 <code>Tool.forward</code>，因为真正的权限、超时、去重可能在派发前后完成。</p><h2 id="model、chatmessage-与模型适配" tabindex="-1"><code>Model</code>、<code>ChatMessage</code> 与模型适配 <a class="header-anchor" href="#model、chatmessage-与模型适配" aria-label="Permalink to &quot;`Model`、`ChatMessage` 与模型适配&quot;">​</a></h2><p><code>models.py</code> 将供应商差异收敛到 <code>Model</code> 接口附近，返回 <code>ChatMessage</code> 或流式 delta。Agent Loop 只关心“这一步模型给了什么文本/调用”，而不应知道某一家 HTTP SDK 的请求字段。</p><h3 id="model" tabindex="-1"><code>Model</code> <a class="header-anchor" href="#model" aria-label="Permalink to &quot;`Model`&quot;">​</a></h3><p>抽象模型的关键不是类名，而是调用契约：输入消息、工具描述、生成参数、流式与非流式结果、token usage 和错误。切换模型时，先检查这几个契约有没有保持，而不是只替换一个构造函数。</p><h3 id="chatmessagetoolcall" tabindex="-1"><code>ChatMessageToolCall</code> <a class="header-anchor" href="#chatmessagetoolcall" aria-label="Permalink to &quot;`ChatMessageToolCall`&quot;">​</a></h3><p>工具调用应包含稳定的调用 id、工具名和参数。这个 id 用于把工具结果回填到同一条对话链；如果重试时生成了新 id，必须确认下游是否会重复执行副作用。</p><h2 id="agentmemory-与-memorystep" tabindex="-1"><code>AgentMemory</code> 与 <code>MemoryStep</code> <a class="header-anchor" href="#agentmemory-与-memorystep" aria-label="Permalink to &quot;`AgentMemory` 与 `MemoryStep`&quot;">​</a></h2><p><code>memory.py</code> 将 system prompt、任务、规划、动作、工具结果和最终答案表示为不同的 step。它不是数据库，也不是长期记忆；它首先是本次 run 的“可重新渲染输入”。</p><h3 id="agentmemory" tabindex="-1"><code>AgentMemory</code> <a class="header-anchor" href="#agentmemory" aria-label="Permalink to &quot;`AgentMemory`&quot;">​</a></h3><p>阅读 <code>AgentMemory</code> 时看三个边界：step 是追加还是可变更新；重新渲染成消息时是否保留工具输出；<code>replay()</code> 展示的内容是否等于真正发送给模型的内容。日志里出现一段文本，不代表它一定被放回下一次请求。</p><h3 id="actionstep" tabindex="-1"><code>ActionStep</code> <a class="header-anchor" href="#actionstep" aria-label="Permalink to &quot;`ActionStep`&quot;">​</a></h3><p><code>ActionStep</code> 连接模型动作、工具/代码执行结果、错误和 token/timing 元数据。它是定位“模型说了什么”和“执行器做了什么”的好入口。</p><h2 id="localpythonexecutor-限制不等于沙箱" tabindex="-1"><code>LocalPythonExecutor</code>：限制不等于沙箱 <a class="header-anchor" href="#localpythonexecutor-限制不等于沙箱" aria-label="Permalink to &quot;`LocalPythonExecutor`：限制不等于沙箱&quot;">​</a></h2><p><code>LocalPythonExecutor</code> 会解析 AST、限制 import、提供受控变量和工具，并捕获执行错误；但它仍在宿主 Python 进程内工作。官方 README 明确警告：它不是安全沙箱，限制可能被绕过，不应运行不受信代码。</p><h3 id="localexecutor-路线中的泛称" tabindex="-1"><code>LocalExecutor</code>：路线中的泛称 <a class="header-anchor" href="#localexecutor-路线中的泛称" aria-label="Permalink to &quot;`LocalExecutor`：路线中的泛称&quot;">​</a></h3><p>路线里的 <code>LocalExecutor</code> 是“本地执行器”的概念名；当前仓库已核对的具体实现叫 <code>LocalPythonExecutor</code>，并通过 <code>PythonExecutor</code> 抽象连接到 <code>CodeAgent</code>。搜索源码时以具体名称为准，不要假设存在一个同名 <code>LocalExecutor</code> 类。</p><h3 id="evaluate-python-code" tabindex="-1"><code>evaluate_python_code</code> <a class="header-anchor" href="#evaluate-python-code" aria-label="Permalink to &quot;`evaluate_python_code`&quot;">​</a></h3><p>它负责把代码转成 AST 并执行支持的节点。断点应放在 import 检查、调用表达式、异常包装和 <code>FinalAnswerException</code> 处理处，观察“禁用语法”与“允许的副作用”是否是同一层策略。</p><h3 id="check-import-authorized" tabindex="-1"><code>check_import_authorized</code> <a class="header-anchor" href="#check-import-authorized" aria-label="Permalink to &quot;`check_import_authorized`&quot;">​</a></h3><p>它只回答某个 import 是否在允许列表，不等于模块本身安全，也不等于文件、网络、进程权限已经被隔离。生产方案必须把它与容器、工作目录、凭据和系统权限一起评估。</p><h3 id="localpythonexecutor-call" tabindex="-1"><code>LocalPythonExecutor.__call__</code> <a class="header-anchor" href="#localpythonexecutor-call" aria-label="Permalink to &quot;`LocalPythonExecutor.__call__`&quot;">​</a></h3><p>这个调用把 action 字符串变为 <code>CodeOutput</code>。对照 <code>CodeAgent._step_stream</code> 阅读，能看清 executor 只负责执行和报告，最终是否继续由 Agent Loop 决定。</p><h2 id="一次最小运行-用-python-伪代码复盘" tabindex="-1">一次最小运行：用 Python 伪代码复盘 <a class="header-anchor" href="#一次最小运行-用-python-伪代码复盘" aria-label="Permalink to &quot;一次最小运行：用 Python 伪代码复盘&quot;">​</a></h2><p>下面的代码是概念性伪代码，故意不依赖网络和模型；它对应源码中“memory → model → executor → stop”的关系。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;"> TinyAgent</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">:</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">    def</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> __init__</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">(self, model, executor, max_steps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">):</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">        self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> model</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">        self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.executor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> executor</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">        self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.max_steps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> max_steps</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">        self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.memory </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> []</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">    def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#DCBDFB;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">(self, task):</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">        self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.memory.append({</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;task&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: task})</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">        for</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> step </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.max_steps):</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">            action </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.model(</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.memory)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">            result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.executor(action)</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;">            self</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">.memory.append({</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: action, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: result})</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">            if</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> result.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;final&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">):</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">                return</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> result[</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">]</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">        raise</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> RuntimeError</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;maximum steps reached&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#768390;"># 输入：一个任务；输出：最终答案或最大步数错误。</span></span></code></pre></div><p>这段代码不是 smolagents 的复制品，而是读源码时的导航尺：真正实现多了流式事件、不同 step 类型、工具 schema、回调、异常包装和模型适配。</p><h2 id="源码阅读锚点" tabindex="-1">源码阅读锚点 <a class="header-anchor" href="#源码阅读锚点" aria-label="Permalink to &quot;源码阅读锚点&quot;">​</a></h2><ol><li>在 <code>MultiStepAgent.run</code> 入口记录 <code>task</code>、<code>max_steps</code> 和初始 tools。</li><li>进入 <code>_run_stream</code>，确认每个 step 的创建和结束位置。</li><li>选择一个分支：工具调用看 <code>ToolCallingAgent.process_tool_calls</code>，代码调用看 <code>CodeAgent._step_stream</code>。</li><li>下钻到 <code>Model</code>，记录消息渲染、工具 schema 和 provider adapter 的边界。</li><li>回到 <code>AgentMemory</code>，验证执行结果如何进入下一轮输入。</li><li>最后读 <code>LocalPythonExecutor</code> 和安全文档，单独标注宿主副作用。</li></ol><p>推荐搜索词：<code>_run_stream</code>、<code>_step_stream</code>、<code>process_tool_calls</code>、<code>execute_tool_call</code>、<code>create_python_executor</code>、<code>AgentMemory</code>、<code>FinalAnswerException</code>、<code>max_steps</code>。</p><h2 id="易混点" tabindex="-1">易混点 <a class="header-anchor" href="#易混点" aria-label="Permalink to &quot;易混点&quot;">​</a></h2><ul><li><code>CodeAgent</code> 的“代码执行”不是自动获得安全隔离；<code>LocalPythonExecutor</code> 只做尽力而为的限制。</li><li><code>AgentMemory</code> 是 run 级步骤历史，不等同于跨会话长期记忆。</li><li><code>run()</code> 返回最终值，不代表中间每一个模型输出都已持久化或可重放。</li><li>工具调用 id、工具名和参数分别承担关联、派发和校验责任。</li><li><code>ToolCallingAgent</code> 与 <code>CodeAgent</code> 共用父类停止逻辑，但动作格式和副作用边界不同。</li></ul><h2 id="课后小问-含解析" tabindex="-1">课后小问（含解析） <a class="header-anchor" href="#课后小问-含解析" aria-label="Permalink to &quot;课后小问（含解析）&quot;">​</a></h2><h3 id="为什么不能只读-tool-forward-就认为工具安全" tabindex="-1">为什么不能只读 <code>Tool.forward</code> 就认为工具安全？ <a class="header-anchor" href="#为什么不能只读-tool-forward-就认为工具安全" aria-label="Permalink to &quot;为什么不能只读 `Tool.forward` 就认为工具安全？&quot;">​</a></h3><p>答案：工具执行前后还有名称发现、参数转换、授权、超时、错误回填和重试边界。<code>Tool.forward</code> 只描述工具本身的业务动作；要判断安全，必须沿 <code>execute_tool_call</code> 和外层 loop 一起看。</p><h3 id="为什么-localpythonexecutor-不能替代容器" tabindex="-1">为什么 <code>LocalPythonExecutor</code> 不能替代容器？ <a class="header-anchor" href="#为什么-localpythonexecutor-不能替代容器" aria-label="Permalink to &quot;为什么 `LocalPythonExecutor` 不能替代容器？&quot;">​</a></h3><p>答案：它运行在当前 Python 进程和宿主权限中，AST/import 限制不是进程、文件系统、网络或凭据隔离。官方 README 也明确把它标成非安全沙箱。</p><h3 id="读到-agentmemory-时最先验证什么" tabindex="-1">读到 <code>AgentMemory</code> 时最先验证什么？ <a class="header-anchor" href="#读到-agentmemory-时最先验证什么" aria-label="Permalink to &quot;读到 `AgentMemory` 时最先验证什么？&quot;">​</a></h3><p>答案：验证“写进 memory 的 step”与“下一次真正发送给模型的消息”之间的转换，避免把日志、展示文本误认为模型上下文。</p><h2 id="本节小结" tabindex="-1">本节小结 <a class="header-anchor" href="#本节小结" aria-label="Permalink to &quot;本节小结&quot;">​</a></h2><p>smolagents 的主线是 <code>MultiStepAgent</code> 驱动循环，<code>CodeAgent</code>/<code>ToolCallingAgent</code> 只替换动作解释方式，<code>Model</code> 负责供应商适配，<code>AgentMemory</code> 负责步骤重渲染，执行器负责执行并报告。安全性尤其要沿执行器边界单独核查。</p><h2 id="快速回顾" tabindex="-1">快速回顾 <a class="header-anchor" href="#快速回顾" aria-label="Permalink to &quot;快速回顾&quot;">​</a></h2><ul><li>入口：<code>MultiStepAgent.run → _run_stream → _step_stream</code>。</li><li>代码路径：<code>CodeAgent → LocalPythonExecutor → CodeOutput</code>。</li><li>工具路径：<code>ToolCallingAgent → process_tool_calls → execute_tool_call</code>。</li><li>状态路径：<code>MemoryStep/ActionStep → AgentMemory → 下一轮模型输入</code>。</li><li>关键风险：本地 Python 执行器不是安全沙箱。</li></ul><h2 id="官方源码与文档" tabindex="-1">官方源码与文档 <a class="header-anchor" href="#官方源码与文档" aria-label="Permalink to &quot;官方源码与文档&quot;">​</a></h2><ul><li><a href="https://github.com/huggingface/smolagents" target="_blank" rel="noreferrer">smolagents 官方仓库</a></li><li><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/agents.py" target="_blank" rel="noreferrer"><code>agents.py</code></a></li><li><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/memory.py" target="_blank" rel="noreferrer"><code>memory.py</code></a></li><li><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/models.py" target="_blank" rel="noreferrer"><code>models.py</code></a></li><li><a href="https://github.com/huggingface/smolagents/blob/main/src/smolagents/local_python_executor.py" target="_blank" rel="noreferrer"><code>local_python_executor.py</code></a></li><li><a href="https://github.com/huggingface/smolagents#security" target="_blank" rel="noreferrer">smolagents 安全说明</a></li></ul>',67);function E(e,f,x,B,q,D){const r=h,d=o("ClientOnly"),c=o("Mermaid");return s(),g("div",null,[_,i(d,null,{default:k(()=>{var a,t;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((t=e.$frontmatter)==null?void 0:t.showArticleMetadata)??!0)?(s(),u(r,{key:0,article:e.$frontmatter},null,8,["article"])):A("",!0)]}),_:1}),C,i(c,{id:"mermaid_64a5706a",graph:"flowchart%20TD%0A%20%20%20%20A%5BMultiStepAgent.run%20task%5D%20--%3E%20B%5B_run_stream%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%86%99%E5%85%A5%20AgentMemory%5D%0A%20%20%20%20C%20--%3E%20D%5B%E6%A8%A1%E5%9E%8B%20Model.__call__%5D%0A%20%20%20%20D%20--%3E%20E%7BAgent%20%E7%B1%BB%E5%9E%8B%7D%0A%20%20%20%20E%20--%3E%7CToolCallingAgent%7C%20F%5B%E8%A7%A3%E6%9E%90%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%5D%0A%20%20%20%20E%20--%3E%7CCodeAgent%7C%20G%5B%E8%A7%A3%E6%9E%90%20Python%20%E4%BB%A3%E7%A0%81%5D%0A%20%20%20%20F%20--%3E%20H%5BTool.forward%5D%0A%20%20%20%20G%20--%3E%20I%5BPythonExecutor%5D%0A%20%20%20%20H%20--%3E%20J%5BActionStep%20%E7%BB%93%E6%9E%9C%5D%0A%20%20%20%20I%20--%3E%20J%0A%20%20%20%20J%20--%3E%20K%7B%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%E6%88%96%E7%BB%A7%E7%BB%AD%7D%0A%20%20%20%20K%20--%3E%7C%E7%BB%A7%E7%BB%AD%7C%20C%0A%20%20%20%20K%20--%3E%7C%E7%BB%93%E6%9D%9F%2F%E8%B6%85%E6%AD%A5%E6%95%B0%7C%20L%5BRunResult%5D"}),b])}const S=p(y,[["render",E]]);export{T as __pageData,S as default};
